export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "07:20。星期六。調查媒體辦公室。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪推門進來。前輩已經到了。比平日早。桌上的終端螢幕亮著。螢光燈管還沒開，只有窗外的灰白光和螢幕的冷光混在一起。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距星期一 06:13——大約一天二十二小時五十三分鐘。悠真失蹤第十二日。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "前輩抬頭。指了指螢幕。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "回信了。今早六點多進來的。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯回信了。昨天下午三點設的期限。他們隔了一個晚上才回。不是即時回覆。是經過一個晚上的內部流程之後才回的。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走到前輩桌邊。看螢幕。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "寄件者——TKS 法務統一對外窗口。收件者——媒體事實確認信箱。主旨——關於貴社公開資料確認之後續回覆。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她往下讀。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "回覆正文。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.TksLegal, character: "TKS法務", dialogue: "感謝貴社前日之確認信。就所列詢問事項，本公司統一回覆如下。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.TksLegal, character: "TKS法務", dialogue: "一、TKS-SYNC 產品線之退役研修資料僅供歷史教學參考，不代表現行運用配置。退役教材中出現之設定名稱、群組編號或參數示例，均可能已於現行版本中廢止或變更。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.TksLegal, character: "TKS法務", dialogue: "二、貴社所引用之地址格式（如 Gxx／nn 類表記）並非 TKS-SYNC 產品專屬之來源唯一識別。同類表記可見於多種公共安全系統之通用群組定址規範，不具備來源唯一性。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.TksLegal, character: "TKS法務", dialogue: "三、歷史研修教材中保留之設定名稱或別名，可能僅為舊版維護用語或教學示例，不代表現行產品之正式命名或功能定義。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.TksLegal, character: "TKS法務", dialogue: "四、有關貴社所詢之歷史配置改訂履歷及特定測試時段之映射紀錄，因涉及系統安全與運用機密，本公司不便提供。後續媒體技術詢問統一由法務暨公關部門受理，請透過本窗口聯繫。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯四條。全部是防禦性措辭。第一條——退役研修資料不代表現行配置。第二條——地址格式不具來源唯一性。第三條——歷史名稱可能只是舊版維護用語。第四條——後續詢問由法務公關統一受理。沒有提到警方。沒有提到兒少研究。沒有提到小野寺。沒有提到小鏡子。沒有提到 G07／12 的案件來源。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他們只回答了能安全回答的東西。退役教材。格式通用。歷史名稱可能是維護用語。法務接管。每一條都是真的。每一條都沒有否認 TOKYO 存在。但也沒有確認任何歷史配置。這不是承認。也不是否認。是收窄。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "前輩靠回椅背。看著澪。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "你怎麼看。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "他們沒有提任何案件相關的東西。只談退役教材、格式通用、歷史名稱可能是維護用語、法務接管。四條。全是防線。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "對。他們現在知道有人在查舊名稱。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯前輩說的不是「他們有罪」。是「他們知道了」。這封信本身——就是一個信號。我們問了公開文件裡出現過的設定檔名稱。他們沒有回答那個名稱是什麼。他們只說——退役教材不代表現行配置，歷史名稱可能只是維護用語。這表示他們內部有人看過了我們的問題。有人判斷了哪些可以回答。有人決定了哪些不能回答。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "這不是證明他們有罪。只代表我們不能再假設公開頁會一直原樣留著。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我知道。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "如果他們要更新公開資料，最可能動的是退役研修教材的線上版本。紙本配布過的東西動不了。但放在伺服器上的研修投影片、線上維護手冊——那些可能會被整理、遮蔽或者直接下架。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯前輩在提醒我。時間有限。如果 TKS 決定收窄公開接觸——線上研修資料可能會在幾天內改變。我必須在公開頁被整理之前，去看已經配布過的紙本。已經調出的。已經放在館架上的。那些不會因為有人改了伺服器而消失。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "前輩打開另一個畫面。轉過螢幕給澪看。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "昨晚我用你抄下來的交付編號送了預約。今早確認回來了。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上是一封來自東京都防災學習館附設研修資料室的預約確認。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "預約編號。調閱者——媒體事實確認信箱。資料包——退役研修教材與離線復舊程序手冊。狀態——已調出。可閱覽時段——今日 10:30 後。館內閱覽。不帶離。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "資料已經調出來了。十點半以後可以看。週六開館。你今天去。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "好。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "規則跟上次差不多。身分證件。閱覽申請現場填。不拆釘，不帶離。可以拍攝，但要館員確認過再拍。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯資料已經調出了。退役研修教材和離線復舊程序手冊。兩個資料包。同一個交付編號鏈。昨晚前輩用 Chapter 14 抄下的交付編號預約的。今早確認——已調出。10:30 以後。今天。現在。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "07:45。澪坐到自己的位置。打開背包。拿出筆記本。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到昨晚最後一頁。6.1。6.2。6.3。三個七。三個詞不畫等號。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到新的一頁。在頂端寫——", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "星期六。悠真失蹤第十二日。距星期一 06:13——約一天二十二小時五十三分鐘。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "下面寫——", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "TKS 媒體回覆。四條。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她逐條抄。退役研修資料不代表現行配置。地址格式不具來源唯一性。歷史名稱可能只是舊版維護用語。後續由法務公關統一受理。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "抄完之後，她在旁邊寫——", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "未提及：警方。兒少研究。小鏡子。小野寺。G07／12。06:13。時間循環。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他們什麼都沒提。不是因為不知道。是因為這封信走的是媒體確認渠道。他們只能回答媒體問的。我們只問了公開文件。他們只回答公開文件能回答的。渠道分離。媒體渠道和警方渠道是兩條線。TKS 法務不會在媒體回覆裡提案件。也不會在警方補充意見裡提媒體詢問。兩邊各自收窄。各自安全。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到下一頁。寫——", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "今日目標。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一——東京都防災學習館附設研修資料室。10:30 後。退役研修教材。離線復舊程序手冊。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二——獨立記錄。不先看 Chapter 5 草圖。先記錄今天看到的。再比較。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯順序不能反。如果我先打開 Chapter 5 的草圖——先看了第一輪畫下的外殼形狀——再去翻退役手冊——我的眼睛會被草圖引導。會專門找像的東西。會跳過不像的。會在無意識裡把新看到的東西往舊記憶上靠。那不是獨立記錄。那是用新資料去填充舊記憶的缺口。結果會變成——我看見了我想看見的。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯所以。先記錄今天的。先拍。先抄。先寫下退役手冊上印了什麼。全部做完之後。回到辦公室。再打開草圖。再比較。順序不能反。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:05。她站起來。走到辦公室角落的鐵製鎖櫃前。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有打開。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她只是站在那裡。看著鎖櫃的門。鑰匙在背包內袋裡。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯草圖在裡面。Chapter 5 封存的。第一輪記憶。未接觸同類硬體資料之前畫下的。正面。側面。破邊。金色接點的大概位置。血下疑似 T 與 7 的痕跡。頁角寫了日期和「第一輪記憶；未接觸同類硬體資料」。密封的。跟鏡背照片放在一起。在鎖櫃最裡面。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不開。今天不開。等今天的資料記錄完了。等退役手冊的整頁照片拍了。等筆記本上寫完了手冊上印的東西。回到這裡。再開鎖櫃。再拿草圖。再比較。順序不能反。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她轉身。走回自己的桌子。把手機拿出來。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:10。她打開通訊軟體。找到佐伯的對話。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯告訴佐伯今天的方向。不提 TKS 回覆的具體措辭——那是媒體渠道的東西。只說我要去研修資料室。只說我在追別紙 C 的交付編號鏈。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她打字。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "今天去防災學習館的研修資料室。用別紙 C 的交付編號預約的。退役研修教材和離線復舊手冊。10:30 開放。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "等。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:18。佐伯回覆了。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "研修資料是公共館藏？", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯佐伯第一句問的是來源性質。不是問我找到了什麼。是問這份東西從哪裡來。公共館藏和公司內部資料是不同的證據層級。他在確認地基。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "對。東京都防災學習館附設研修資料室。半公共設施。週六開放。舊盒裝教材需提前預約。退役型號。館內閱覽。可拍攝。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "退役的？", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "對。型號已退役。金鑰帳號端點表已刪除。研修材料在新版遮蔽規則統一前送存。一般硬體外形和已廢止別名被視為低風險歷史資料。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "等。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "低風險歷史資料才能館內閱覽。如果是現行配置，不會放在公共館。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "對。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "別紙 C 的交付編號——你從哪裡拿到的？", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "Chapter 14 安全委員會紙本附件裡的引用編號。公開配布資料。委員會章。收件戳。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "公開文件引用了不公開文件的編號。你用編號去公共館追被引用的資料包。合法。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "對。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "看到什麼先記錄。不要先跟記憶比對。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯佐伯跟我說的一樣。先記錄。不要先比對。他見過太多家屬把新看到的東西往舊記憶上靠。他知道污染是怎麼發生的。不是故意的。是自動的。大腦會填缺口。會把像的東西看成同一個。會把模糊的邊緣修清楚。修清楚之後——就分不清哪部分是原本記得的，哪部分是後來填進去的。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "我知道。先獨立記錄。不先看草圖。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "草圖還封著？", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "在辦公室鎖櫃。沒開。今天記錄完再開。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "好。看到什麼傳給我。只傳公開部分。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "好。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把手機放下。看著筆記本。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:30。前輩那邊的終端傳來一聲提示音。前輩看了一眼。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "TKS 回覆已經存檔了。署名編輯看過。沒有需要追問的措辭問題。下週再討論後續——要不要發正式採訪申請。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "好。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.MediaSenior, character: "調查媒體前輩", dialogue: "今天回來以後把研修資料的拍攝清單整理給我。我幫你確認引用鏈。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "好。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:40。澪收好筆記本。收好手機。站起來。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走到門口。停了一秒。回頭看了一眼鎖櫃。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯草圖在裡面。第一輪的。未污染的。等今天結束——再打開。順序不能反。", background: Background.Chapter_15_Ch15_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她開門。走出去。", background: Background.Chapter_15_Ch15_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:25。電車。往東京都防災學習館方向。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "車廂裡人不多。星期六上午。她站在車門旁邊。背包帶勒在肩上。筆記本在背包裡。手機在口袋裡。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯TKS 知道有人在查舊名稱了。他們不會在媒體回覆裡提案件。但他們內部會做什麼——我不知道。他們可能會整理線上研修資料。可能會遮蔽退役教材裡的舊名稱。可能會下架某些頁面。也可能什麼都不做。我不知道。我只知道——紙本配布過的東西動不了。已經調出的資料包不會因為有人改了伺服器而消失。", background: Background.Chapter_15_Ch15_Act1_S1, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯今天的目標。退役研修教材。離線復舊程序手冊。別紙 C 的交付編號鏈。如果研修教材裡有 TOKYO 的舊名稱——有別名——有維護用語——那就是別紙 C 不公開的原因。不是因為名字本身是秘密。是因為名字背後連著一份不公開的用途文件。我要找的是——名字。名字先找到。用途之後再追。", background: Background.Chapter_15_Ch15_Act1_S1, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:50。她下了電車。走出車站。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "防災學習館在一條安靜的街上。灰色建築。門口有防災宣傳旗幟。週六。有幾組家庭帶小孩在入口附近走動。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她站在門口。看了一眼手機。10:02。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯還有二十八分鐘。10:30 才開放閱覽。先進去。先找研修資料室的位置。先確認預約。", background: Background.Chapter_15_Ch15_Act1_S1, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走進建築。大廳裡有防災模型展示。地震體驗區的標誌。一群小學生在老師帶領下排隊。旁邊有退役消防設備展示。牆上有防災學習館的開放時間表。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "研修資料室在二樓。指標寫著——附設研修資料室（預約制）。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走上樓梯。二樓走廊。盡頭有一扇門。門上貼著——研修資料室。開放時間：週六 10:30–16:30。預約制。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "門是關的。透過門上的玻璃窗可以看到裡面——一排排金屬架。架上有盒裝資料。紙本目錄抽屜。幾張閱覽桌。日光燈。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在門口等。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯二十八分鐘。等。不急。資料已經調出了。不會跑掉。今天要做的事很清楚。獨立記錄。不先看草圖。整頁拍攝。頁碼。交付編號。改訂日期。上下文。館藏登錄資訊。不只拍名字。拍名字出現的那一整頁。", background: Background.Chapter_15_Ch15_Act1_S1, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "10:15。門裡傳來動靜。一個穿著館員背心的職員走到門邊。打開門。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "早安。有預約嗎？", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "有。媒體事實確認信箱預約的。退役研修教材和離線復舊程序手冊。", background: Background.Chapter_15_Ch15_Act1_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "請稍等，我確認一下。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "職員翻看櫃台上的預約清單。找到了。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "確認了。兩個資料包都調出了。十點半正式開放閱覽。請先在這裡填閱覽申請。需要身分證件。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "好。", background: Background.Chapter_15_Ch15_Act1_S1, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "10:20。澪坐在閱覽室門口的填表台前。填寫申請單。姓名。證件號碼。調閱目的——公開資料查證。資料包編號。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她填完。交給職員。職員核對身分證件。登記。在預約清單上打勾。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "10:28。職員走向後方資料架。取下兩個牛皮紙盒。盒脊上貼著標籤。交付編號。改訂日期。退役標記。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "職員把兩個盒子放在閱覽桌上。指定座位。第二桌。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "10:30。研修資料室正式開放。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在第二桌前。兩個盒子放在面前。她沒有立刻打開。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她先拿出筆記本。翻到空白頁。拿起筆。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在頁面頂端寫——", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "Chapter 15。研修資料室。獨立記錄。未參照第一輪草圖。", background: Background.Chapter_15_Ch15_Act1_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯開始。先記錄。不比對。不回想。只寫眼前這些紙上印了什麼。", background: Background.Chapter_15_Ch15_Act1_S1, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她打開第一個盒子。", background: Background.Chapter_15_Ch15_Act1_S1 },
];
